"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["17564"],{74237(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.resolvedor_arvore_satisfacao.arvore_estruturalmente_invalida","status":422,"titulo":"A \xe1rvore de exig\xeancias congelada tem identidade repetida entre folhas"},"descricao":{"codigo":"uniplus.selecao.resolvedor_arvore_satisfacao.arvore_estruturalmente_invalida","requisitos":[],"oQueAconteceu":["Ao avaliar os documentos exigidos, o sistema percorre a \xe1rvore de exig\xeancias documentais do processo.\\nAntes de decidir qualquer coisa, ele confere se a \xe1rvore tem a forma que a defini\xe7\xe3o sempre produz, e a\\n\xe1rvore avaliada n\xe3o tem. A mensagem diz qual dos dois casos ocorreu:","- a mesma exig\xeancia aparece em mais de uma folha: cada exig\xeancia precisa de identidade \xfanica, para que\\n  o documento apresentado seja correlacionado a uma folha s\xf3;\\n- uma sub\xe1rvore marcada como repetida por entidade (por exemplo, por membro do grupo familiar) cont\xe9m\\n  outra sub\xe1rvore tamb\xe9m repetida: a repeti\xe7\xe3o n\xe3o aninha, e avaliar assim apagaria em sil\xeancio as\\n  consequ\xeancias da repeti\xe7\xe3o interna.","A \xe1rvore avaliada depende da opera\xe7\xe3o:","- Na avalia\xe7\xe3o, no salvamento do rascunho e no envio da inscri\xe7\xe3o, a recusa se refere \xe0 configura\xe7\xe3o publicada, n\xe3o ao que a pessoa preencheu. Nada da inscri\xe7\xe3o enviada \xe9 gravado por este pedido, e repeti-lo n\xe3o muda o resultado. A defini\xe7\xe3o dos documentos exigidos recusa a repeti\xe7\xe3o aninhada ([`repeticao_de_entidade_aninhada`](/erros/uniplus.selecao.no_exigencia.repeticao_de_entidade_aninhada)), e a integridade da configura\xe7\xe3o \xe9 conferida antes ([`integridade_violada`](/erros/uniplus.selecao.envelope_codec.integridade_violada)). Esta causa s\xf3 aparece se a configura\xe7\xe3o foi publicada com esse defeito.\\n- Na pr\xe9-visualiza\xe7\xe3o do processo seletivo, a recusa se refere \xe0 configura\xe7\xe3o em edi\xe7\xe3o, em rascunho ou em retifica\xe7\xe3o. Ela ainda pode ser alterada e nada \xe9 gravado.","Uma folha sem exig\xeancia \xe9 recusada antes, na leitura da configura\xe7\xe3o publicada, como [`envelope_malformado`](/erros/uniplus.selecao.envelope_codec.envelope_malformado)."],"comoResolver":["Nas opera\xe7\xf5es da inscri\xe7\xe3o, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a configura\xe7\xe3o\\ncongelada da vers\xe3o publicada, e a pessoa que se inscreve n\xe3o consegue corrigi-la. A causa \xe9 investigada\\npela equipe t\xe9cnica do Uni+.","Na pr\xe9-visualiza\xe7\xe3o, a causa est\xe1 na configura\xe7\xe3o viva do processo. Confira os documentos exigidos\\ndefinidos nele: cada folha precisa de uma exig\xeancia pr\xf3pria, e nenhuma sub\xe1rvore repetida por entidade\\npode conter outra. Se a \xe1rvore parecer correta, a causa \xe9 investigada pela equipe t\xe9cnica do Uni+.\\nDepois de corrigir, repita a pr\xe9-visualiza\xe7\xe3o."],"ondeAparece":["Avalia\xe7\xe3o da inscri\xe7\xe3o","Salvamento do rascunho da inscri\xe7\xe3o","Envio da inscri\xe7\xe3o do candidato","Pr\xe9-visualiza\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Resolvedor arvore satisfacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);